package com.phoenix.business.web; import com.phoenix.business.domain.MembershipPlan;import com.phoenix.business.repository.MembershipPlanRepository;import com.phoenix.business.service.AuditService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/api/plans") @RequiredArgsConstructor public class PlanController {private final MembershipPlanRepository repo;private final AuditService audit;record Input(@NotBlank @Size(max=100)String name,@Min(1)int durationMonths,@DecimalMin("0")BigDecimal price,@Size(max=500)String description,Boolean active){}@GetMapping public List<MembershipPlan> list(){return repo.findAll();}@PostMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public MembershipPlan create(@Valid @RequestBody Input q){MembershipPlan p=new MembershipPlan();copy(p,q);p=repo.save(p);audit.record("PLAN_CREATED","PLAN",p.getId(),p.getName());return p;}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public MembershipPlan update(@PathVariable Long id,@Valid @RequestBody Input q){MembershipPlan p=repo.findById(id).orElseThrow();copy(p,q);p=repo.save(p);audit.record("PLAN_UPDATED","PLAN",id,p.getName());return p;}private void copy(MembershipPlan p,Input q){if(repo.existsByNameIgnoreCaseAndIdNot(q.name(),p.getId()==null?0:p.getId()))throw new IllegalArgumentException("Plan name already exists");p.setName(q.name().trim());p.setDurationMonths(q.durationMonths());p.setPrice(q.price());p.setDescription(q.description());p.setActive(q.active()==null||q.active());}}
